ANALYSIS:
- Field: .statement.predicate.buildConfig.tasks[]
  Access: via lib.tasks_from_pipelinerun
  Role: Iterate all pipeline tasks to check for expiring trusted references.
  Notes: lib.tasks_from_pipelinerun aggregates tasks from all PipelineRun attestations.

- Field: task reference (bundle or git)
  Access: via tekton.task_ref(task) → {key, pinned_ref}
  Role: Provides the canonical key for looking up in trusted_tasks data.
  Notes: Works with both OCI bundle resolver and git resolver.

- Field: trusted_tasks data
  Access: via tekton.expiry_of(task) which internally uses lib.rule_data and data.trusted_tasks
  Role: Determines if the task's current ref has an upcoming expiry.
  Logic:
    - tekton.expiry_of returns the expiry timestamp only if within warning window
    - Returns undefined if not expiring soon or already expired

- Helper Selection:
  - lib.tasks_from_pipelinerun: Convenient accessor for all tasks across attestations
  - tekton.expiry_of: Encapsulates expiry window logic, respects task_expiry_warning_days
  - tekton.pipeline_task_name: For error message (the name users see in Pipeline)
  - tekton.task_name: For the searchable term (the actual Task name)
  - tekton.latest_trusted_ref: To suggest upgrade path in message
  - time.format: Convert nanoseconds to readable date
  - lib.result_helper_with_term: Generate result with metadata and searchable term

- Message Template:
  The failure_msg from METADATA is: "A newer version of task %q exists. Please update before %s. The current bundle is %q and the latest bundle ref is %q"
  Args needed: [pipeline_task_name, expiry_date, current_bundle_info, latest_ref]

RULE:
```rego
package trusted_task

import rego.v1

import data.lib
import data.lib.tekton

# METADATA
# title: Tasks using the latest versions
# description: >-
#   Check if all Tekton Tasks use the latest known Task reference. When warnings
#   will be reported can be configured using the `task_expiry_warning_days` rule
#   data setting. It holds the number of days before the task is to expire within
#   which the warnings will be reported.
# custom:
#   short_name: current
#   failure_msg: >-
#     A newer version of task %q exists. Please update before %s.
#     The current bundle is %q and the latest bundle ref is %q
#   solution: >-
#     Update the Task reference to a newer version.
#   collections:
#   - redhat
#   - redhat_rpms
#   effective_on: 2024-05-07T00:00:00Z
#
warn contains result if {
	some task in lib.tasks_from_pipelinerun
	expiry := tekton.expiry_of(task)
	result := lib.result_helper_with_term(
		rego.metadata.chain(),
		[tekton.pipeline_task_name(task), time.format(expiry), _task_info(task), tekton.latest_trusted_ref(task)],
		tekton.task_name(task),
	)
}

_task_info(task) := info if {
	ref := tekton.task_ref(task)
	info := sprintf("%s@%s", [object.get(ref, "key", ""), object.get(ref, "pinned_ref", "")])
}
```

TESTS:
```rego
package trusted_task_test

import rego.v1

import data.lib
import data.trusted_task

# Test: trusted task with far expiry - no warning
test_no_warning_latest_version if {
	att := {"statement": {"predicate": {
		"buildType": lib.tekton_pipeline_run,
		"buildConfig": {"tasks": [trusted_bundle_pipeline_task]},
	}}}

	lib.assert_empty(trusted_task.warn) with input.attestations as [att]
		with data.trusted_tasks as trusted_tasks_data
}

# Test: outdated task expiring soon - warn
test_outdated_warning if {
	att := {"statement": {"predicate": {
		"buildType": lib.tekton_pipeline_run,
		"buildConfig": {"tasks": [
			trusted_bundle_pipeline_task,
			outdated_bundle_pipeline_task,
		]},
	}}}

	expected := {{
		"code": "trusted_task.current",
		# regal ignore:line-length
		"msg": `A newer version of task "outdated-trusty-p" exists. Please update before 2099-01-01T00:00:00Z. The current bundle is "oci://registry.local/trusty:1.0@sha256:outdated-digest" and the latest bundle ref is "sha256:digest"`,
		"term": "trusty",
	}}

	lib.assert_equal_results(trusted_task.warn, expected) with input.attestations as [att]
		with data.trusted_tasks as trusted_tasks_data
}

# Test: git resolver outdated task - warn
test_outdated_git_warning if {
	att := {"statement": {"predicate": {
		"buildType": lib.tekton_pipeline_run,
		"buildConfig": {"tasks": [
			trusted_git_pipeline_task,
			outdated_git_pipeline_task,
		]},
	}}}

	expected := {{
		"code": "trusted_task.current",
		# regal ignore:line-length
		"msg": `A newer version of task "outdated-honest-abe-p" exists. Please update before 2099-01-01T00:00:00Z. The current bundle is "git+git.local/repo.git//tasks/honest-abe.yaml@37ef630394794f28142224295851a45eea5c63ae" and the latest bundle ref is "48df630394794f28142224295851a45eea5c63ae"`,
		"term": "honest-abe",
	}}

	lib.assert_equal_results(trusted_task.warn, expected) with input.attestations as [att]
		with data.trusted_tasks as trusted_tasks_data
}

